"""Consistent JSON error handling.

Every error response uses the envelope:
    {"error": {"code": <machine-readable>, "message": <human-readable>, "details": {...}}}
"""
from flask import Flask, jsonify
from marshmallow import ValidationError
from werkzeug.exceptions import HTTPException


class ApiError(Exception):
    """Raise anywhere in a request to produce a structured JSON error."""

    def __init__(self, message: str, status_code: int = 400, code: str = "bad_request", details=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.code = code
        self.details = details or {}


def error_response(status_code: int, code: str, message: str, details=None):
    payload = {"error": {"code": code, "message": message, "details": details or {}}}
    return jsonify(payload), status_code


_HTTP_CODES = {
    400: "bad_request",
    401: "unauthorized",
    403: "forbidden",
    404: "not_found",
    405: "method_not_allowed",
    409: "conflict",
    415: "unsupported_media_type",
    422: "unprocessable_entity",
    429: "rate_limit_exceeded",
    500: "internal_server_error",
}


def register_error_handlers(app: Flask) -> None:
    @app.errorhandler(ApiError)
    def handle_api_error(err: ApiError):
        return error_response(err.status_code, err.code, err.message, err.details)

    @app.errorhandler(ValidationError)
    def handle_validation_error(err: ValidationError):
        return error_response(422, "validation_error", "Input validation failed.", err.messages)

    @app.errorhandler(HTTPException)
    def handle_http_exception(err: HTTPException):
        code = _HTTP_CODES.get(err.code, "error")
        return error_response(err.code or 500, code, err.description or err.name)

    @app.errorhandler(Exception)
    def handle_unexpected(err: Exception):  # pragma: no cover - safety net
        app.logger.exception("Unhandled exception")
        if app.config.get("TESTING") or app.config.get("DEBUG"):
            raise err
        return error_response(500, "internal_server_error", "An unexpected error occurred.")

"""Marshmallow schemas for input validation."""
from marshmallow import Schema, fields, validate, EXCLUDE


class StrictSchema(Schema):
    class Meta:
        unknown = EXCLUDE


class RegisterSchema(StrictSchema):
    email = fields.Email(required=True)
    password = fields.String(
        required=True,
        validate=validate.Length(min=8, max=128, error="Password must be 8-128 characters."),
    )


class LoginSchema(StrictSchema):
    email = fields.Email(required=True)
    password = fields.String(required=True)


class ItemCreateSchema(StrictSchema):
    name = fields.String(required=True, validate=validate.Length(min=1, max=120))
    description = fields.String(load_default="", validate=validate.Length(max=5000))
    price = fields.Decimal(
        required=True,
        as_string=False,
        validate=validate.Range(min=0, error="Price must be non-negative."),
    )


class ItemUpdateSchema(StrictSchema):
    name = fields.String(validate=validate.Length(min=1, max=120))
    description = fields.String(validate=validate.Length(max=5000))
    price = fields.Decimal(validate=validate.Range(min=0, error="Price must be non-negative."))


class PaginationSchema(StrictSchema):
    page = fields.Integer(load_default=1, validate=validate.Range(min=1))
    per_page = fields.Integer(load_default=None, validate=validate.Range(min=1))

"""Pagination helper producing a consistent envelope with navigation links."""
from flask import current_app, request, url_for

from .errors import ApiError
from .schemas import PaginationSchema


def paginate(query, serializer=lambda obj: obj.to_dict()):
    args = PaginationSchema().load(request.args)
    page = args["page"]
    per_page = args["per_page"] or current_app.config["DEFAULT_PAGE_SIZE"]
    max_per_page = current_app.config["MAX_PAGE_SIZE"]
    if per_page > max_per_page:
        raise ApiError(
            f"per_page must not exceed {max_per_page}.",
            status_code=400,
            code="invalid_pagination",
        )

    p = query.paginate(page=page, per_page=per_page, error_out=False)

    def page_url(page_num):
        args = request.args.to_dict()
        args.update({"page": page_num, "per_page": per_page})
        return url_for(request.endpoint, **request.view_args, **args, _external=False)

    return {
        "data": [serializer(item) for item in p.items],
        "meta": {
            "page": page,
            "per_page": per_page,
            "total_items": p.total,
            "total_pages": p.pages,
        },
        "links": {
            "self": page_url(page),
            "next": page_url(p.next_num) if p.has_next else None,
            "prev": page_url(p.prev_num) if p.has_prev else None,
            "first": page_url(1),
            "last": page_url(p.pages or 1),
        },
    }

"""Authentication endpoints: register, login, refresh, me."""
from flask import jsonify, request
from flask_jwt_extended import (
    create_access_token,
    create_refresh_token,
    get_jwt_identity,
    jwt_required,
)

from ...audit import set_audit_action
from ...errors import ApiError
from ...extensions import db, limiter
from ...models import User
from ...schemas import LoginSchema, RegisterSchema
from . import bp


def _json_body() -> dict:
    if not request.is_json:
        raise ApiError(
            "Request body must be JSON.", status_code=415, code="unsupported_media_type"
        )
    return request.get_json(silent=True) or {}


def _tokens_for(user: User) -> dict:
    identity = str(user.id)
    claims = {"role": user.role}
    return {
        "access_token": create_access_token(identity=identity, additional_claims=claims),
        "refresh_token": create_refresh_token(identity=identity),
        "token_type": "Bearer",
    }


@bp.post("/auth/register")
@limiter.limit("10 per minute")
def register():
    data = RegisterSchema().load(_json_body())
    if User.query.filter_by(email=data["email"]).first():
        raise ApiError("Email already registered.", status_code=409, code="email_taken")
    user = User(email=data["email"])
    user.set_password(data["password"])
    db.session.add(user)
    db.session.commit()
    set_audit_action("auth.register", f"user={user.email}")
    return jsonify({"user": user.to_dict(), **_tokens_for(user)}), 201


@bp.post("/auth/login")
@limiter.limit("10 per minute")
def login():
    data = LoginSchema().load(_json_body())
    user = User.query.filter_by(email=data["email"]).first()
    if user is None or not user.check_password(data["password"]):
        set_audit_action("auth.login_failed", f"email={data['email']}")
        raise ApiError("Invalid email or password.", status_code=401, code="invalid_credentials")
    set_audit_action("auth.login", f"user={user.email}")
    return jsonify({"user": user.to_dict(), **_tokens_for(user)})


@bp.post("/auth/refresh")
@jwt_required(refresh=True)
@limiter.limit("30 per minute")
def refresh():
    user = db.session.get(User, int(get_jwt_identity()))
    if user is None:
        raise ApiError("User no longer exists.", status_code=401, code="unknown_user")
    set_audit_action("auth.refresh", f"user={user.email}")
    return jsonify(
        {
            "access_token": create_access_token(
                identity=str(user.id), additional_claims={"role": user.role}
            ),
            "token_type": "Bearer",
        }
    )


@bp.get("/auth/me")
@jwt_required()
def me():
    user = db.session.get(User, int(get_jwt_identity()))
    if user is None:
        raise ApiError("User no longer exists.", status_code=401, code="unknown_user")
    return jsonify({"user": user.to_dict()})

"""Item CRUD: authenticated, validated, paginated, audited."""
from flask import jsonify, request
from flask_jwt_extended import get_jwt, get_jwt_identity, jwt_required

from ...audit import set_audit_action
from ...errors import ApiError
from ...extensions import db, limiter
from ...models import Item
from ...pagination import paginate
from ...schemas import ItemCreateSchema, ItemUpdateSchema
from . import bp


def _json_body() -> dict:
    if not request.is_json:
        raise ApiError(
            "Request body must be JSON.", status_code=415, code="unsupported_media_type"
        )
    return request.get_json(silent=True) or {}


def _get_owned_item(item_id: int) -> Item:
    item = db.session.get(Item, item_id)
    if item is None:
        raise ApiError("Item not found.", status_code=404, code="not_found")
    user_id = int(get_jwt_identity())
    if item.owner_id != user_id and get_jwt().get("role") != "admin":
        raise ApiError("You do not own this item.", status_code=403, code="forbidden")
    return item


@bp.get("/items")
@jwt_required()
@limiter.limit("60 per minute")
def list_items():
    query = Item.query.order_by(Item.id)
    owner_id = request.args.get("owner_id", type=int)
    if owner_id is not None:
        query = query.filter_by(owner_id=owner_id)
    return jsonify(paginate(query))


@bp.get("/items/<int:item_id>")
@jwt_required()
def get_item(item_id: int):
    item = db.session.get(Item, item_id)
    if item is None:
        raise ApiError("Item not found.", status_code=404, code="not_found")
    return jsonify({"data": item.to_dict()})


@bp.post("/items")
@jwt_required()
@limiter.limit("30 per minute")
def create_item():
    data = ItemCreateSchema().load(_json_body())
    item = Item(
        name=data["name"],
        description=data["description"],
        price=data["price"],
        owner_id=int(get_jwt_identity()),
    )
    db.session.add(item)
    db.session.commit()
    set_audit_action("item.create", f"item_id={item.id}")
    return jsonify({"data": item.to_dict()}), 201


@bp.patch("/items/<int:item_id>")
@jwt_required()
def update_item(item_id: int):
    item = _get_owned_item(item_id)
    data = ItemUpdateSchema().load(_json_body())
    if not data:
        raise ApiError("No valid fields to update.", status_code=400, code="empty_update")
    for field, value in data.items():
        setattr(item, field, value)
    db.session.commit()
    set_audit_action("item.update", f"item_id={item.id} fields={sorted(data)}")
    return jsonify({"data": item.to_dict()})


@bp.delete("/items/<int:item_id>")
@jwt_required()
def delete_item(item_id: int):
    item = _get_owned_item(item_id)
    db.session.delete(item)
    db.session.commit()
    set_audit_action("item.delete", f"item_id={item_id}")
    return "", 204

